function rem() {
    var unameEl = document.getElementById('uname');
    var paswdEl = document.getElementById('paswd');
    var remEl = document.getElementById('remember');
    if (!unameEl || !remEl) return;

    var uname = unameEl.value;
    var paswd = paswdEl ? paswdEl.value : uname;
    var isRemember = remEl.checked;

    if (isRemember && uname) {
        var date = new Date();
        date.setTime(date.getTime() + (259200 * 1000)); // 3 days
        var expire = date.toGMTString();
        document.cookie = 'uname=' + encodeURIComponent(uname) + ';expires=' + expire + ';path=/';
        document.cookie = 'paswd=' + encodeURIComponent(paswd) + ';expires=' + expire + ';path=/';
    }
}

function getCookie() {
    var uname = '';
    var paswd = '';
    var SP = document.cookie.split(';');
    for (var i = 0; i < SP.length; i++) {
        var pair = SP[i].trim();
        if (pair.indexOf('uname=') === 0) {
            uname = decodeURIComponent(pair.substring(6));
        }
        if (pair.indexOf('paswd=') === 0) {
            paswd = decodeURIComponent(pair.substring(6));
        }
    }

    if (uname) {
        var unameEl = document.getElementById('uname');
        var paswdEl = document.getElementById('paswd');
        if (unameEl && !unameEl.value) {
            unameEl.value = uname;
        }
        if (paswdEl && !paswdEl.value) {
            paswdEl.value = paswd || uname;
        }
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', getCookie);
} else {
    getCookie();
}
